WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_rank_multiple'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '倍数排序', 'kp-xingce-data-rank-multiple', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "倍数排序"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "“是几倍”和“多几倍”的大小排序完全一致，不影响单调性。利用单调性减免多余计算。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题目问：“下列主体中，2023年产值比2022年‘多’的倍数，按从大到小排序是？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心原理"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“多几倍”的计算式是：现期/基期 - 1。但是！减去 1 是一个常数操作，完全不改变序列的单调性！"}]}, {"type": "katexBlock", "attrs": {"content": "\\text{如果 } X > Y > Z, \\text{ 那么必然有 } (X-1) > (Y-1) > (Z-1)"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[阅读题干, 问的是'多'的倍数排序] --> B[大脑自动抹掉那个'-1']\nB --> C[直接把问题转化为排序 现期量/基期量 的大小]\nC --> D[等同于纯粹的分数比较问题]\nD --> E[使用大大则大、倍数比对等法则出结果]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 2023年某地市产量：甲(200，去年50)，乙(300，去年100)，丙(400，去年80)。问比去年产量多出的倍数排序？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "识别陷阱：题目求的是“多出的倍数”，理论上要分别计算 200/50-1, 300/100-1, 400/80-1。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "忽略 -1：在排序题里，直接排 200/50, 300/100, 400/80。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "直算商：甲=4，乙=3，丙=5。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "出结论：丙 > 甲 > 乙。如果傻傻去减1得出 甲=3, 乙=2, 丙=4，结果也是完全一样的，但你浪费了减法的操作时间。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "图表给倍数时的视力坑：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "如果图表中直接用折线图给出了各个主体的增速或倍数，那这就是纯纯的视力测试。千万别在这个时候又去拿材料的绝对量重新算一遍！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "牢记单调性。资料分析里只要是求排序，加减同一个常数、乘除同一个常数（如化单位、算基期同分母）统统可以无视。"}]}]}$$ AS jsonb), NULL, '倍数排序的核心考点与实战推导。', category_node.id, CAST('["资料分析", "倍数排序"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_rank_multiple", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
